    var HOLIDAY_URLS = {
      cdn: "https://cdn.jsdelivr.net/gh/NateScarlet/holiday-cn@master/{year}.json",
      raw: "https://raw.githubusercontent.com/NateScarlet/holiday-cn/master/{year}.json",
    };

    /** True when the built-in snapshot carries published day lists for a year
     *  (keys are string years, e.g. "2026"). Pure — used by the view's
     *  "update holiday data" hint and directly unit-testable. */
    function snapshotHasYear(year) {
      var key = String(year);
      var y = PANDA_HOLIDAY_SNAPSHOT ? PANDA_HOLIDAY_SNAPSHOT[key] : null;
      return !!y && Array.isArray(y.days) && y.days.length > 0;
    }

    /** Normalize a holiday-cn year payload into {year, byDate, ranges}.
     *  byDate: { "YYYY-MM-DD": {name, off} } ; ranges: contiguous runs of
     *  off-days sharing the same name: {name, start:"YYYY-MM-DD", end, days}. */
    function normalizeHolidayData(payload) {
      var byDate = {};
      var ranges = [];
      if (!payload || !Array.isArray(payload.days)) return { year: null, byDate: byDate, ranges: ranges };
      var sorted = payload.days.slice().sort(function (a, b) { return a.date < b.date ? -1 : a.date > b.date ? 1 : 0; });
      var run = null;
      for (var i = 0; i < sorted.length; i++) {
        var d = sorted[i];
        var off = !!d.isOffDay;
        byDate[d.date] = { name: d.name || "", off: off };
        if (!off) continue; // 调休上班日 not part of a 假期 range
        if (run && run.name === d.name && runEndsToday(run, d.date)) {
          run.end = d.date;
          run.days++;
          run.byDate.push(d.date);
        } else {
          if (run) ranges.push(run);
          run = { name: d.name || "", start: d.date, end: d.date, days: 1, byDate: [d.date] };
        }
      }
      if (run) ranges.push(run);
      // attach per-day ordinal ("春节假期第 2 天")
      for (var r = 0; r < ranges.length; r++) {
        for (var k = 0; k < ranges[r].byDate.length; k++) {
          var dt = ranges[r].byDate[k];
          var hit = byDate[dt];
          hit.holiday = ranges[r].name;
          hit.dayNo = k + 1;
          hit.total = ranges[r].days;
        }
      }
      return { year: payload.year, byDate: byDate, ranges: ranges };
    }

    function runEndsToday(run, date) {
      // end stored as YYYY-MM-DD; next calendar day of run.end equals date?
      var parts = run.end.split("-");
      var t = new Date(Date.UTC(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]) + 1));
      var y = t.getUTCFullYear(), m = t.getUTCMonth() + 1, d = t.getUTCDate();
      var pad = function (n) { return n < 10 ? "0" + n : String(n); };
      return y + "-" + pad(m) + "-" + pad(d) === date;
    }

    /** statInfo(y,m,d) -> null | {name, off, holiday, dayNo, total} */
    function statOf(y, m, d, data) {
      var pad = function (n) { return n < 10 ? "0" + n : String(n); };
      var key = y + "-" + pad(m) + "-" + pad(d);
      var by = (data && data.byDate) || {};
      var hit = by[key];
      if (!hit) return null;
      var out = { name: hit.name, off: hit.off };
      if (hit.holiday) {
        out.holiday = hit.holiday;
        out.dayNo = hit.dayNo;
        out.total = hit.total;
      }
      return out;
    }

    /** fetchYear(year, opts): fetch holiday-cn JSON for a year. Tries CDN then
     *  GitHub raw. opts.fetchImpl must return a promise of a Response-like
     *  object ({ok, json()}) — defaults to global fetch. Resolves to parsed
     *  payload, or null when all sources fail. */
    function fetchYearData(year, opts) {
      opts = opts || {};
      var fetchImpl = opts.fetchImpl || (typeof fetch === "function" ? fetch.bind(null) : null);
      if (!fetchImpl) return Promise.resolve(null);
      var urls = [HOLIDAY_URLS.cdn.replace("{year}", year), HOLIDAY_URLS.raw.replace("{year}", year)];
      var attempt = function (i) {
        if (i >= urls.length) return Promise.resolve(null);
        return fetchImpl(urls[i])
          .then(function (res) {
            if (!res || !res.ok) return attempt(i + 1);
            return res.json().then(function (j) {
              if (!j || !Array.isArray(j.days)) return attempt(i + 1);
              return j;
            });
          })
          .catch(function () { return attempt(i + 1); });
      };
      return attempt(0);
    }

    function loadStatData(year, storage) {
      // returns normalized data or null; tries storage -> snapshot -> network
      var st = storage || null;
      var key = "pandaCalendar.holiday." + year;
      var cached = null;
      if (st && typeof st.getItem === "function") {
        try { cached = JSON.parse(st.getItem(key) || "null"); } catch (e) { cached = null; }
      }
      if (cached && Array.isArray(cached.days)) return normalizeHolidayData(cached);
      var snap = PANDA_HOLIDAY_SNAPSHOT[String(year)];
      if (snap && Array.isArray(snap.days)) return normalizeHolidayData(snap);
      return null;
    }

    function saveStatData(year, payload, storage) {
      var st = storage || null;
      if (!st || typeof st.setItem !== "function") return;
      try { st.setItem("pandaCalendar.holiday." + year, JSON.stringify(payload)); } catch (e) { /* ignore quota */ }
    }

    /* ============================ weather layer ============================ */
    /* Open-Meteo (free, keyless, CC-BY-4.0 data, CORS-open). WMO weather
       codes mapped to zh/en display text + a short pictogram. */

    var WMO_TEXT = [
      // [code, zh, en, icon]
      [0, "晴", "Clear", "☀"], [1, "大致晴朗", "Mostly clear", "🌤"], [2, "多云", "Partly cloudy", "⛅"],
      [3, "阴", "Overcast", "☁"], [45, "雾", "Foggy", "🌫"], [48, "雾凇", "Rime fog", "🌫"],
      [51, "毛毛雨", "Light drizzle", "🌦"], [53, "毛毛雨", "Drizzle", "🌦"], [55, "毛毛雨", "Dense drizzle", "🌧"],
      [56, "冻毛毛雨", "Freezing drizzle", "🌧"], [57, "冻毛毛雨", "Dense freezing drizzle", "🌧"],
      [61, "小雨", "Light rain", "🌦"], [63, "中雨", "Rain", "🌧"], [65, "大雨", "Heavy rain", "🌧"],
      [66, "冻雨", "Freezing rain", "🌧"], [67, "冻雨", "Heavy freezing rain", "🌧"],
      [71, "小雪", "Light snow", "🌨"], [73, "中雪", "Snow", "🌨"], [75, "大雪", "Heavy snow", "❄"],
      [77, "雪粒", "Snow grains", "❄"], [80, "小阵雨", "Light showers", "🌦"], [81, "阵雨", "Showers", "🌧"],
      [82, "强阵雨", "Violent showers", "⛈"], [85, "小阵雪", "Light snow showers", "🌨"], [86, "阵雪", "Snow showers", "❄"],
      [95, "雷雨", "Thunderstorm", "⛈"], [96, "雷雨伴冰雹", "Thunderstorm w/ hail", "⛈"], [99, "强雷暴伴冰雹", "Severe thunderstorm", "⛈"],
    ];

    function weatherCodeInfo(code) {
      for (var i = 0; i < WMO_TEXT.length; i++) {
        if (WMO_TEXT[i][0] === code) return { zh: WMO_TEXT[i][1], en: WMO_TEXT[i][2], icon: WMO_TEXT[i][3] };
      }
      return { zh: "未知", en: "Unknown", icon: "❔" };
    }

    var DEFAULT_CITIES = [
      { name: "北京", en: "Beijing", lat: 39.9042, lon: 116.4074 },
      { name: "上海", en: "Shanghai", lat: 31.2304, lon: 121.4737 },
      { name: "广州", en: "Guangzhou", lat: 23.1291, lon: 113.2644 },
      { name: "深圳", en: "Shenzhen", lat: 22.5431, lon: 114.0579 },
      { name: "杭州", en: "Hangzhou", lat: 30.2741, lon: 120.1551 },
      { name: "成都", en: "Chengdu", lat: 30.5728, lon: 104.0668 },
      { name: "武汉", en: "Wuhan", lat: 30.5928, lon: 114.3055 },
      { name: "西安", en: "Xi'an", lat: 34.3416, lon: 108.9398 },
    ];

    /** Normalize an Open-Meteo forecast payload into a compact shape. */
    function normalizeForecast(payload) {
      if (!payload || !payload.current || !payload.daily) return null;
      var c = payload.current;
      var cur = {
        time: c.time,
        temp: c.temperature_2m,
        feels: c.apparent_temperature,
        humidity: c.relative_humidity_2m,
        wind: c.wind_speed_10m,
        isDay: c.is_day === 1,
        code: c.weather_code,
        info: weatherCodeInfo(c.weather_code),
      };
      var daily = [];
      var dl = payload.daily;
      for (var i = 0; i < (dl.time || []).length; i++) {
        daily.push({
          date: dl.time[i],
          code: dl.weather_code ? dl.weather_code[i] : null,
          info: dl.weather_code ? weatherCodeInfo(dl.weather_code[i]) : null,
          tMax: dl.temperature_2m_max ? dl.temperature_2m_max[i] : null,
          tMin: dl.temperature_2m_min ? dl.temperature_2m_min[i] : null,
          rainProb: dl.precipitation_probability_max ? dl.precipitation_probability_max[i] : null,
          uv: dl.uv_index_max ? dl.uv_index_max[i] : null,
          sunrise: dl.sunrise ? dl.sunrise[i] : null,
          sunset: dl.sunset ? dl.sunset[i] : null,
        });
      }
      return { current: cur, daily: daily, timezone: payload.timezone || "", updated: new Date().toISOString() };
    }

    function openMeteoFetch(fetchImpl, url) {
      return fetchImpl(url).then(function (res) {
        if (!res || !res.ok) return null;
        return res.json().catch(function () { return null; });
      });
    }

    /** 7-day/3-day forecast for lat/lon. Resolves normalized object or null. */
    function fetchWeather(lat, lon, opts) {
      opts = opts || {};
      var fetchImpl = opts.fetchImpl || (typeof fetch === "function" ? fetch.bind(null) : null);
      if (!fetchImpl || lat == null || lon == null) return Promise.resolve(null);
      var days = opts.days || 3;
      var u = "https://api.open-meteo.com/v1/forecast?latitude=" + lat + "&longitude=" + lon +
        "&current=temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,weather_code,wind_speed_10m" +
        "&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,uv_index_max,sunrise,sunset" +
        "&timezone=auto&forecast_days=" + days;
      return openMeteoFetch(fetchImpl, u).then(normalizeForecast);
    }

    /** Geocode a city query -> [{name, admin1, country, lat, lon}] */
    function searchCity(q, opts) {
      opts = opts || {};
      var fetchImpl = opts.fetchImpl || (typeof fetch === "function" ? fetch.bind(null) : null);
      if (!fetchImpl || !q) return Promise.resolve([]);
      var u = "https://geocoding-api.open-meteo.com/v1/search?name=" + encodeURIComponent(q) +
        "&count=5&language=zh&format=json";
      return openMeteoFetch(fetchImpl, u).then(function (j) {
        if (!j || !Array.isArray(j.results)) return [];
        return j.results.map(function (r) {
          return { name: r.name, admin1: r.admin1 || "", country: r.country || "", lat: r.latitude, lon: r.longitude };
        });
      });
    }

    /** Reverse geocode via BigDataCloud reverse-geocode-client (keyless, CORS). */
    function reverseGeocode(lat, lon, opts) {
      opts = opts || {};
      var fetchImpl = opts.fetchImpl || (typeof fetch === "function" ? fetch.bind(null) : null);
      if (!fetchImpl || lat == null || lon == null) return Promise.resolve(null);
      var u = "https://api.bigdatacloud.net/data/reverse-geocode-client?latitude=" + lat +
        "&longitude=" + lon + "&localityLanguage=zh";
      return fetchImpl(u).then(function (res) {
        if (!res || !res.ok) return null;
        return res.json().catch(function () { return null; });
      }).then(function (j) {
        if (!j) return null;
        return {
          city: j.city || j.locality || j.principalSubdivision || "",
          country: j.countryName || "",
          lat: j.latitude,
          lon: j.longitude,
        };
      });
    }

    /** City-level locate by IP via ip-api.com (HTTP, keyless, CORS-open).
     *  Resolves {city, country, countryCode, lat, lon} or null. */
    function locateByIp(opts) {
      opts = opts || {};
      // explicit null disables the fallback to the ambient fetch
      var fetchImpl = opts.fetchImpl === undefined
        ? (typeof fetch === "function" ? fetch.bind(null) : null)
        : opts.fetchImpl;
      if (!fetchImpl) return Promise.resolve(null);
      var u = "https://ip-api.com/json/?lang=zh-CN&fields=status,message,country,countryCode,city,lat,lon,query";
      return fetchImpl(u).then(function (res) {
        if (!res || !res.ok) return null;
        return res.json().catch(function () { return null; });
      }).then(function (j) {
        if (!j || j.status !== "success") return null;
        return {
          city: j.city || "",
          country: j.country || "",
          countryCode: j.countryCode || "",
          lat: j.lat,
          lon: j.lon,
          ip: j.query || "",
        };
      });
    }

    /* ---- city list + active city persistence ---------------------------------
       localStorage-backed so user-added cities survive plugin updates and
       reinstalls (localStorage lives on the browser origin, not in the npm
       package). One versioned record { list, active }. The storage object is
       injectable for tests; the default is the browser localStorage. Corrupt
       or foreign data degrades to null (caller then falls back to defaults),
       never to a crash. */
    var CITY_STORE_KEY = "pandaCalendar.cities.v1";

    function defaultBrowserStorage() {
      try {
        return (typeof localStorage !== "undefined" && localStorage) || null;
      } catch (err) { return null; }
    }

    function isValidCity(c) {
      return !!c && typeof c === "object" &&
        typeof c.name === "string" && c.name.length > 0 &&
        typeof c.lat === "number" && isFinite(c.lat) &&
        typeof c.lon === "number" && isFinite(c.lon);
    }

    /** Read { list, active } from storage; null when absent/corrupt/empty. */
    function loadCityState(storage) {
      var st = storage === undefined ? defaultBrowserStorage() : storage;
      if (!st || typeof st.getItem !== "function") return null;
      var raw = null;
      try { raw = st.getItem(CITY_STORE_KEY); } catch (err) { return null; }
      if (!raw) return null;
      var parsed = null;
      try { parsed = JSON.parse(raw); } catch (err) { return null; }
      if (!parsed || !Array.isArray(parsed.list)) return null;
      var list = parsed.list.filter(isValidCity);
      if (list.length === 0) return null;
      var active = (typeof parsed.active === "string" &&
        list.some(function (c) { return c.name === parsed.active; }))
        ? parsed.active : list[0].name;
      return { list: list, active: active };
    }

    /** Persist { list, active }. Invalid entries are dropped; an active city
     *  not in the list falls back to the first city. Silently no-ops when no
     *  writable storage exists (private mode / quota). */
    function saveCityState(list, active, storage) {
      var st = storage === undefined ? defaultBrowserStorage() : storage;
      if (!st || typeof st.setItem !== "function" || !Array.isArray(list)) return;
      var clean = list.filter(isValidCity);
      if (clean.length === 0) return;
      var act = (typeof active === "string" &&
        clean.some(function (c) { return c.name === active; }))
        ? active : clean[0].name;
      try {
        st.setItem(CITY_STORE_KEY, JSON.stringify({ list: clean, active: act }));
      } catch (err) { /* quota/private: keep in-memory only */ }
    }

    /** One-shot "where am I": browser geolocation -> reverse geocode, with
     *  ip-api.com as the fallback when geolocation is missing or denied.
     *  Resolves { name, lat, lon } or null. opts: { fetchImpl, geolocation }
     *  injectable for tests (defaults to the ambient browser APIs). */
    function locateCurrentCity(opts) {
      opts = opts || {};
      var fetchImpl = opts.fetchImpl === undefined
        ? (typeof fetch === "function" ? fetch.bind(null) : null)
        : opts.fetchImpl;
      var geo = opts.geolocation !== undefined ? opts.geolocation
        : (typeof navigator !== "undefined" && navigator.geolocation ? navigator.geolocation : null);
      var viaGeo = function () {
        return new Promise(function (resolve) {
          if (!geo || typeof geo.getCurrentPosition !== "function") return resolve(null);
          var settled = false;
          var done = function (v) { if (!settled) { settled = true; resolve(v); } };
          try {
            geo.getCurrentPosition(function (pos) {
              var lat = pos.coords.latitude, lon = pos.coords.longitude;
              reverseGeocode(lat, lon, { fetchImpl: fetchImpl }).then(function (rc) {
                if (rc && rc.city) done({ name: rc.city, lat: rc.lat || lat, lon: rc.lon || lon });
                else done(null);
              }, function () { done(null); });
            }, function () { done(null); }, { timeout: 6000, maximumAge: 600000 });
          } catch (err) { done(null); }
        });
      };
      var viaIp = function () {
        return locateByIp({ fetchImpl: fetchImpl }).then(function (ip) {
          if (!ip || !ip.city) return null;
          return { name: ip.city, lat: ip.lat, lon: ip.lon };
        });
      };
      return viaGeo().then(function (hit) {
        if (hit) return hit;
        return viaIp();
      });
    }

